#!/usr/bin/env node
/**
 * The quality report a pull request carries, generated by the pipeline instead of by a person.
 *
 * ## Why this exists
 *
 * The report it replaces was assembled by hand: someone ran the gates locally, copied the numbers
 * into a comment, and posted it. That works exactly once. The next release has no report, or worse,
 * has one whose numbers came from a different tree than the one under review — which is the failure
 * this repository keeps finding in other shapes (a green run that published nothing, a guard with no
 * caller, a warning inside an unreachable branch).
 *
 * So every number here is read from the run being reported on: check conclusions come from the
 * GitHub API for the head SHA, and coverage comes from the artifact the `coverage` job uploaded.
 * Nothing is passed in by hand and nothing is defaulted.
 *
 * ## The invariant that matters most
 *
 * **A check that has not finished is not a check that passed.** `summarise` counts it as pending and
 * refuses `ok`, and the rendered report names it. A report that rounds "still running" up to green
 * is worse than no report: it is read as a verdict, and it is not one. The same rule applies to
 * coverage — when the artifact is missing, the report says it could not read it rather than omitting
 * the row, because an absent row reads as "there is no coverage gate".
 *
 * Usage (in CI):
 *   node scripts/pr-quality-report.mjs --checks checks.json --coverage coverage-summary.json \
 *        --sha "$SHA" > report.md
 */

/** Marker the workflow greps for, so the comment is updated in place instead of duplicated. */
export const REPORT_MARKER = '<!-- theokit:quality-report -->'

/** Conclusions that mean "this gate did not apply", as opposed to passing or failing. */
const NEUTRAL = new Set(['skipped', 'neutral'])
const PASSING = new Set(['success'])

/**
 * Fold a list of check runs into counts plus the names that still need attention.
 *
 * `ok` is deliberately conservative: it requires at least one check, zero failures AND zero pending.
 * An empty list is not green — it means nothing reported, which is a different fact.
 */
export function summarise(checkRuns) {
  const s = { passed: 0, failed: 0, pending: 0, skipped: 0, outstanding: [], ok: false }

  for (const run of checkRuns) {
    if (run.status !== 'completed') {
      s.pending += 1
      s.outstanding.push(run.name)
      continue
    }
    if (PASSING.has(run.conclusion)) s.passed += 1
    else if (NEUTRAL.has(run.conclusion)) s.skipped += 1
    else {
      s.failed += 1
      s.outstanding.push(run.name)
    }
  }

  s.ok = checkRuns.length > 0 && s.failed === 0 && s.pending === 0
  return s
}

const AXES = [
  ['lines', 'Lines'],
  ['statements', 'Statements'],
  ['functions', 'Functions'],
  ['branches', 'Branches'],
]

function coverageSection(coverage, floor) {
  if (coverage === null || coverage === undefined) {
    return [
      '### Coverage',
      '',
      '> The coverage artifact **was not read** on this run, so no figure is shown. A missing number',
      '> is not a missing gate — `Coverage gate` above is what fails the build; this row only reports',
      '> what it measured.',
    ].join('\n')
  }

  const rows = AXES.filter(([key]) => coverage[key]).map(([key, label]) => {
    const a = coverage[key]
    // Only lines carries a gate; the other axes are context, and a column that repeated the same
    // floor beside them would imply three thresholds where there is one.
    const threshold = key === 'lines' ? `${floor} %` : '—'
    return `| ${label} | ${a.pct} % | ${a.covered} / ${a.total} | ${threshold} |`
  })

  return [
    '### Coverage',
    '',
    '| Axis | % | Covered | Floor |',
    '|---|---:|---:|---:|',
    ...rows,
  ].join('\n')
}

function checksSection(checkRuns, s) {
  const icon = (r) => {
    if (r.status !== 'completed') return '⏳'
    if (PASSING.has(r.conclusion)) return '✅'
    if (NEUTRAL.has(r.conclusion)) return '⏭️'
    return '❌'
  }

  const sorted = [...checkRuns].sort((a, b) => a.name.localeCompare(b.name))
  const rows = sorted.map((r) => `| ${icon(r)} | ${r.name} | \`${r.conclusion ?? r.status}\` |`)

  const head = s.ok
    ? `**${s.passed} of ${s.passed + s.skipped} gates passed.**`
    : [
        '**Not green.**',
        s.failed > 0 ? `${s.failed} failed` : null,
        s.pending > 0 ? `${s.pending} still running` : null,
        checkRuns.length === 0 ? 'no check reported at all' : null,
      ]
        .filter(Boolean)
        .join(' · ')

  const outstanding =
    s.outstanding.length > 0
      ? ['', '**Needs attention:**', ...s.outstanding.map((n) => `- ${n}`)].join('\n')
      : ''

  return [
    '### Gates',
    '',
    head,
    outstanding,
    '',
    '| | Gate | Result |',
    '|---|---|---|',
    ...rows,
  ].join('\n')
}

/**
 * @param sha           the commit these numbers describe — printed so a reader can tell whether the
 *                      report is about the diff they are looking at
 * @param coverageFloor the line-coverage floor, for context beside the measured value
 */
export function renderReport({ checkRuns, coverage, sha, coverageFloor = 80 }) {
  const s = summarise(checkRuns)

  return [
    REPORT_MARKER,
    '## Quality report',
    '',
    `Measured on \`${sha}\`. Generated by the pipeline — every figure comes from this run.`,
    '',
    checksSection(checkRuns, s),
    '',
    coverageSection(coverage, coverageFloor),
    '',
    '---',
    '',
    '<sub>A check that is still running counts as **pending**, never as passed. When coverage cannot',
    'be read the report says so rather than dropping the row.</sub>',
  ].join('\n')
}

// ── CLI ────────────────────────────────────────────────────────────────────

function arg(name) {
  const i = process.argv.indexOf(`--${name}`)
  return i === -1 ? undefined : process.argv[i + 1]
}

async function main() {
  const { readFileSync } = await import('node:fs')
  const read = (p) => {
    if (p === undefined) return null
    try {
      return JSON.parse(readFileSync(p, 'utf8'))
    } catch {
      return null // absent or unparseable — the report says so rather than inventing a value
    }
  }

  const checks = read(arg('checks'))
  const coverageFile = read(arg('coverage'))

  process.stdout.write(
    renderReport({
      checkRuns: checks?.check_runs ?? checks ?? [],
      coverage: coverageFile?.total ?? null,
      sha: arg('sha') ?? 'unknown',
      coverageFloor: Number(arg('floor') ?? 80),
    }) + '\n',
  )
}

if (import.meta.url === `file://${process.argv[1]}`) await main()
